const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const region = ee.Geometry.Rectangle([-180, -68, 180, -56]); // 56°S to 68°S, global longitude
  const date = '2016-01-13';

  // 2. Data Acquisition - MODIS chlorophyll for phytoplankton detection
  // Try MODIS Aqua (better for ocean color) first
  let collection = ee.ImageCollection('MODIS/Aqua/L3SMI')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filterBounds(region)
    .select('chlor_a'); // Chlorophyll-a concentration

  let size = collection.size().getInfo();
  console.log(`MODIS Aqua Images: ${size}`);

  // Fallback to MODIS Terra if Aqua has no data
  if (size === 0) {
    collection = ee.ImageCollection('MODIS/Terra/L3SMI')
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .filterBounds(region)
      .select('chlor_a');
    size = collection.size().getInfo();
    console.log(`MODIS Terra Images: ${size}`);
  }

  // Check for no data
  if (size === 0) {
    console.log("C1");
    return;
  }

  // 3. Processing - Use mean composite for the day
  const image = collection.mean().clip(region);

  // Count valid pixels (chlorophyll > 0 indicates water pixels)
  const stats = image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 5000, // MODIS scale
    maxPixels: 1e9
  });

  const pixelCount = stats.get('chlor_a').getInfo();
  console.log(`Valid ocean pixels: ${pixelCount}`);

  // Check for no valid pixels
  if (pixelCount === 0) {
    console.log("C2");
    return;
  }

  // 4. Calculation - Detect bloom (chlorophyll > threshold)
  // Typical bloom threshold: >1 mg/m³ for Southern Ocean
  const bloomThreshold = 1.0;
  const bloomPixels = image.gt(bloomThreshold).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).get('chlor_a').getInfo();

  const bloomPercentage = (bloomPixels / pixelCount * 100).toFixed(2);
  console.log(`Bloom pixels (chl > ${bloomThreshold}): ${bloomPixels}`);
  console.log(`Bloom coverage: ${bloomPercentage}%`);

  // 5. Validation & Final Answer
  if (bloomPercentage === null || bloomPercentage === undefined || 
      bloomPercentage < 0 || bloomPercentage > 100) {
    console.log("C3");
    return;
  }

  // Bloom considered "visible" if at least 5% coverage
  if (bloomPercentage >= 5) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
